adcs_status_t st_dip;

if (rate == NULL || command == NULL || torque == NULL) {
    return ADCS_E_NULL;
}

rate->x = 0.0;
rate->y = 0.0;
rate->z = 0.0;
command->command->x = 0.0;
command->command->y = 0.0;
command->command->z = 0.0;
command->saturated_axes = 0U;
torque->x = 0.0;
torque->y = 0.0;
torque->z = 0.0;

if (previous == NULL || current == NULL) {
    return ADCS_E_NULL;
}

if ((!adcs_is_finite_vec3(previous)) || (!adcs_is_finite_vec3(current)) ||
    (!isfinite(previous_time)) || (!isfinite(current_time)) ||
    (current_time <= previous_time)) {
    return ADCS_E_RANGE;
}

if ((!isfinite(gain)) || (!isfinite(limit)) || (gain < 0.0) || (limit < 0.0)) {
    return ADCS_E_RANGE;
}

bdot_state.previous_field_t = *previous;
bdot_state.previous_time_s = previous_time;
bdot_state.initialized = 1;

local_rate.x = 0.0;
local_rate.y = 0.0;
local_rate.z = 0.0;
st = adcs_bdot_update(&bdot_state, current, current_time, 1.0, &local_rate);
if (st != ADCS_OK) {
    return st;
}

local_command.command->x = 0.0;
local_command.command->y = 0.0;
local_command.command->z = 0.0;
local_command.saturated_axes = 0U;
st_dip = adcs_bdot_dipole(current, &local_rate, gain, limit, &local_command);
if (st_dip != ADCS_OK) {
    return st_dip;
}

local_torque = adcs_vec3_cross(&local_command.command, current);

*rate = local_rate;
*command = local_command;
*torque = local_torque;
return ADCS_OK;

